import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2018-Jun-28 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Jun-28 :: Ceph Performance Weekly","date":"2018-06-28T00:00:00.000Z","updated":"2018-06-29T00:00:00.000Z","tags":["Ceph","Performance","Memory Allocator","Optimization","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Jun-28_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Jun-28_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),o={name:"posts/2018/2018-Jun-28_-_-_Ceph_Performance_Weekly.md"};function r(p,l,n,c,s,_){return i(),a("div",null,[...l[0]||(l[0]=[t("<p>在本次Ceph性能周会中，研发团队讨论了多个关键议题，包括内存分配器性能、线程行为优化、pull request评估等。</p><ol><li><p><strong>内存分配器</strong>：</p><ul><li>讨论了不同内存分配器的性能和碎片化问题，包括stupid allocator、bitmap allocator和libc malloc。</li><li>测试结果表明，libc malloc在内存使用上表现不佳，而TC malloc和J malloc在性能和内存使用上更优。</li><li>团队决定继续使用TC malloc或J malloc作为Ceph的默认内存分配器，并探讨了优化libc malloc的方法。</li></ul></li><li><p><strong>KVS线程和finisher线程</strong>：</p><ul><li>讨论了KVS线程和finisher线程的行为，以及Majin pang提出的改进方案。</li><li>Majin pang的改进方案在高并发情况下表现出良好的性能提升。</li><li>团队决定进一步研究Majin pang的改进方案，并评估其在生产环境中的效果。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>讨论了静态链接、bitmap分配器碎片化、异步恢复、大页内存等pull request。</li><li>讨论了make check性能优化和缓存利用率的提高。</li><li>讨论了app tracker优化和分区优化。</li><li>讨论了libc malloc的性能测试结果。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>继续使用TC malloc或J malloc作为Ceph的默认内存分配器。</li><li>进一步研究Majin pang的KVS线程和finisher线程改进方案。</li><li>优化make check性能，提高缓存利用率。</li><li>集成p2t wrapper，优化app tracker。</li><li>考虑使用libc malloc的优化方法。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>Majin pang将提供更多关于KVS线程和finisher线程改进方案的信息。</li><li>进行libc malloc的优化测试，并评估其效果。</li><li>对其他讨论的pull request进行评估和合并。</li><li>继续优化Ceph的性能和稳定性。</li></ul></li></ol>",2)])])}const d=e(o,[["render",r]]);export{u as __pageData,d as default};
